namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public int TotalRating { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRating / RatingCount : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle with olive oil.",
            TotalRating = 18, RatingCount = 4
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Egg yolks, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture quickly.\n6. Serve immediately with extra pecorino.",
            TotalRating = 15, RatingCount = 3
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer.\n5. Stir in cream and garam masala.\n6. Add chicken pieces and simmer 10 minutes.",
            TotalRating = 20, RatingCount = 4
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar, Eggs",
            Steps = "1. Soak rice noodles in warm water.\n2. Mix tamarind paste, fish sauce, and sugar for sauce.\n3. Stir-fry tofu until golden.\n4. Scramble eggs in the pan.\n5. Add noodles and sauce, toss well.\n6. Top with bean sprouts, peanuts, and lime.",
            TotalRating = 12, RatingCount = 3
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder",
            Steps = "1. Brown ground beef with cumin and chili powder.\n2. Warm taco shells in oven.\n3. Dice tomato and shred lettuce.\n4. Assemble tacos with beef, lettuce, tomato.\n5. Top with cheese and sour cream.\n6. Serve with salsa and lime wedges.",
            TotalRating = 8, RatingCount = 2
        },
        new Recipe
        {
            Id = 6, Title = "Green Curry", Category = "Thai",
            Ingredients = "Green curry paste, Coconut milk, Chicken breast, Thai basil, Bamboo shoots, Bell pepper, Fish sauce",
            Steps = "1. Heat coconut cream until oil separates.\n2. Fry curry paste until fragrant.\n3. Add sliced chicken and cook through.\n4. Pour in coconut milk and bring to simmer.\n5. Add vegetables and bamboo shoots.\n6. Season with fish sauce, serve over jasmine rice.",
            TotalRating = 10, RatingCount = 2
        }
    };

    private int _nextId = 7;

    public IReadOnlyList<Recipe> GetAll() => _recipes.AsReadOnly();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            recipe.TotalRating += stars;
            recipe.RatingCount++;
        }
    }
}

